def combinationSum2(candidates, target):
    cands = sorted(candidates)
    res, cur = [], []
    def bt(start, rem):
        if rem == 0:
            res.append(cur[:])
            return
        for i in range(start, len(cands)):
            if cands[i] > rem:
                break
            if i > start and cands[i] == cands[i - 1]:
                continue
            cur.append(cands[i])
            bt(i + 1, rem - cands[i])
            cur.pop()
    bt(0, target)
    return res

