import itertools
def combinationSum2(candidates, target):
    out = set()
    for k in range(len(candidates) + 1):
        for c in itertools.combinations(candidates, k):
            if sum(c) == target:
                out.add(tuple(sorted(c)))
    return [list(t) for t in out]

